/**
 * 原生端实现的事件接收器。
 *
 * 回调可能从 Rust 工作线程调用；Kotlin/Swift 实现必须自行切回 UI 线程。
 */
public protocol NativeEventSink: AnyObject, Sendable {
    
    /**
     * 接收一条与 Tauri Channel 逐字节同构的 JSON 事件。
     */
    func onEvent(eventJson: String) 
    
}


// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceNativeEventSink {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceNativeEventSink] = [UniffiVTableCallbackInterfaceNativeEventSink(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceNativeEventSink.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface NativeEventSink: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceNativeEventSink.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface NativeEventSink: handle missing in uniffiClone")
            }
        },
        onEvent: { (
            uniffiHandle: UInt64,
            eventJson: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceNativeEventSink.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onEvent(
                     eventJson: try FfiConverterString.lift(eventJson)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )]
}

private func uniffiCallbackInitNativeEventSink() {
    uniffi_yunjian_mobile_fn_init_callback_vtable_nativeeventsink(UniffiCallbackInterfaceNativeEventSink.vtable)
}

